<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Image Preview</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f3f6fb;
        --panel: #ffffff;
        --panel-strong: #101828;
        --text: #0f172a;
        --muted: #475467;
        --border: #d0d5dd;
        --shadow: 0 24px 60px rgba(15, 23, 42, 0.16);
        --primary: #155eef;
        --danger: #d92d20;
        --danger-strong: #b42318;
        --surface-soft: #f8fafc;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(21, 94, 239, 0.12), transparent 32%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
        color: var(--text);
      }

      button {
        font: inherit;
      }

      button:focus-visible,
      dialog:focus-visible {
        outline: 3px solid #84adff;
        outline-offset: 3px;
      }

      .page-shell {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 24px;
      }

      .app-card {
        width: min(100%, 960px);
        background: rgba(255, 255, 255, 0.84);
        backdrop-filter: blur(16px);
        border: 1px solid rgba(208, 213, 221, 0.7);
        border-radius: 28px;
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .app-grid {
        display: grid;
        grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.9fr);
      }

      .preview-panel,
      .details-panel {
        padding: 32px;
      }

      .preview-panel {
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(248, 250, 252, 0.92));
        border-right: 1px solid rgba(208, 213, 221, 0.75);
      }

      .eyebrow {
        margin: 0 0 8px;
        color: var(--primary);
        font-size: 0.8rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0 0 12px;
        font-size: clamp(1.9rem, 4vw, 2.6rem);
        line-height: 1.05;
      }

      .lead,
      .meta-value,
      .status-text {
        color: var(--muted);
      }

      .lead {
        margin: 0 0 24px;
        max-width: 34rem;
        line-height: 1.6;
      }

      .image-frame {
        position: relative;
        border-radius: 24px;
        overflow: hidden;
        background: var(--surface-soft);
        border: 1px solid rgba(208, 213, 221, 0.8);
        min-height: 320px;
      }

      .image-frame img,
      .deleted-state {
        display: block;
        width: 100%;
        min-height: 320px;
      }

      .image-frame img {
        object-fit: cover;
      }

      .deleted-state {
        display: none;
        align-items: center;
        justify-content: center;
        text-align: center;
        padding: 32px;
        background: linear-gradient(135deg, #eff4ff, #f8fafc);
        color: var(--muted);
      }

      .deleted-state strong {
        display: block;
        color: var(--panel-strong);
        font-size: 1.1rem;
        margin-bottom: 8px;
      }

      .preview-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 12px;
        margin-top: 20px;
      }

      .button {
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.2rem;
        font-weight: 700;
        cursor: pointer;
        transition: transform 140ms ease, box-shadow 140ms ease, background 140ms ease;
      }

      .button:hover {
        transform: translateY(-1px);
      }

      .button-primary {
        background: var(--primary);
        color: #fff;
        box-shadow: 0 14px 28px rgba(21, 94, 239, 0.24);
      }

      .button-secondary {
        background: #fff;
        color: var(--text);
        border: 1px solid var(--border);
      }

      .button-danger {
        background: var(--danger);
        color: #fff;
        box-shadow: 0 14px 28px rgba(217, 45, 32, 0.24);
      }

      .button[disabled] {
        cursor: not-allowed;
        opacity: 1;
        color: #98a2b3;
        background: #eaecf0;
        box-shadow: none;
        transform: none;
      }

      .details-panel {
        display: flex;
        flex-direction: column;
        gap: 18px;
      }

      .details-card {
        padding: 20px;
        border-radius: 20px;
        background: rgba(248, 250, 252, 0.95);
        border: 1px solid rgba(208, 213, 221, 0.85);
      }

      .details-card h2 {
        margin: 0 0 14px;
        font-size: 1rem;
      }

      .meta-list {
        display: grid;
        gap: 12px;
      }

      .meta-item {
        display: flex;
        justify-content: space-between;
        gap: 16px;
        align-items: start;
      }

      .meta-label {
        font-weight: 700;
      }

      .status {
        display: inline-flex;
        align-items: center;
        gap: 10px;
        padding: 10px 14px;
        border-radius: 999px;
        background: #ecfdf3;
        color: #027a48;
        font-weight: 700;
      }

      .status::before {
        content: "";
        width: 10px;
        height: 10px;
        border-radius: 50%;
        background: currentColor;
      }

      .status-text {
        margin: 0;
        line-height: 1.6;
      }

      dialog {
        width: min(100% - 32px, 430px);
        padding: 0;
        border: 0;
        border-radius: 24px;
        box-shadow: 0 30px 80px rgba(15, 23, 42, 0.28);
      }

      dialog::backdrop {
        background: rgba(15, 23, 42, 0.55);
        backdrop-filter: blur(6px);
      }

      .dialog-card {
        padding: 28px;
        background: var(--panel);
      }

      .dialog-icon {
        width: 48px;
        height: 48px;
        display: grid;
        place-items: center;
        border-radius: 14px;
        background: #fef3f2;
        color: var(--danger);
        margin-bottom: 18px;
        font-size: 1.4rem;
      }

      .dialog-title {
        margin: 0 0 10px;
        font-size: 1.35rem;
      }

      .dialog-copy {
        margin: 0;
        color: var(--muted);
        line-height: 1.6;
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap-reverse;
        justify-content: flex-end;
        gap: 12px;
        margin-top: 24px;
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      }

      @media (max-width: 760px) {
        .app-grid {
          grid-template-columns: 1fr;
        }

        .preview-panel {
          border-right: 0;
          border-bottom: 1px solid rgba(208, 213, 221, 0.75);
        }

        .preview-panel,
        .details-panel {
          padding: 24px;
        }

        .preview-actions,
        .dialog-actions {
          flex-direction: column;
        }

        .button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        .app-card,
        .details-card,
        .image-frame,
        dialog,
        .button-secondary,
        .button-primary,
        .button-danger {
          border: 1px solid ButtonText;
        }

        .button-primary,
        .button-danger,
        .button-secondary,
        .status,
        .dialog-icon {
          background: Canvas;
          color: ButtonText;
          box-shadow: none;
        }

        dialog::backdrop {
          background: rgba(0, 0, 0, 0.6);
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script>
      const imageUrl =
        "data:image/svg+xml;utf8," +
        encodeURIComponent(`
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 1000" role="img" aria-label="Mountain lake at sunset">
            <defs>
              <linearGradient id="sky" x1="0%" y1="0%" x2="0%" y2="100%">
                <stop offset="0%" stop-color="#11346F" />
                <stop offset="45%" stop-color="#3A72E2" />
                <stop offset="100%" stop-color="#F9C784" />
              </linearGradient>
              <linearGradient id="water" x1="0%" y1="0%" x2="1" y2="1">
                <stop offset="0%" stop-color="#2246A6" />
                <stop offset="100%" stop-color="#60A5FA" />
              </linearGradient>
            </defs>
            <rect width="1600" height="1000" fill="url(#sky)" />
            <circle cx="1230" cy="235" r="94" fill="#FFE7A3" />
            <path d="M0 690 L310 385 L540 640 L745 428 L955 650 L1160 490 L1385 675 L1600 560 L1600 1000 L0 1000 Z" fill="#163D78" />
            <path d="M0 760 C260 680 410 640 590 680 C760 720 995 840 1600 740 L1600 1000 L0 1000 Z" fill="url(#water)" />
            <path d="M0 820 C290 760 470 730 650 760 C860 800 1110 920 1600 800" stroke="#D7F0FF" stroke-width="16" fill="none" opacity="0.8" />
          </svg>
        `);

      function Button({ className = "", type = "button", label, extra = "" }) {
        return `<button type="${type}" class="button ${className}" ${extra}>${label}</button>`;
      }

      function MetaRow(label, value) {
        return `
          <div class="meta-item">
            <span class="meta-label">${label}</span>
            <span class="meta-value">${value}</span>
          </div>
        `;
      }

      function ImagePreview() {
        return `
          <section class="preview-panel" aria-labelledby="page-title">
            <p class="eyebrow">Library</p>
            <h1 id="page-title">Image preview</h1>
            <p class="lead">
              Review this photo before making changes to your library. Deleting removes it from your saved items.
            </p>

            <div class="image-frame">
              <img
                id="preview-image"
                src="${imageUrl}"
                alt="Mountain lake at sunset with blue water and a bright sky"
              />
              <div id="deleted-state" class="deleted-state" tabindex="-1">
                <div>
                  <strong>Image removed</strong>
                  This photo has been deleted from your library.
                </div>
              </div>
            </div>

            <div class="preview-actions">
              ${Button({
                className: "button-secondary",
                label: "Download"
              })}
              ${Button({
                className: "button-danger trigger",
                label: "Delete image",
                extra: 'id="open-dialog" aria-haspopup="dialog" aria-controls="delete-dialog"'
              })}
            </div>
          </section>
        `;
      }

      function ImageDetails() {
        return `
          <aside class="details-panel" aria-label="Image details">
            <div class="details-card">
              <div class="status">Synced to library</div>
              <p class="status-text" id="status-message" aria-live="polite">
                This image is currently available in your personal collection.
              </p>
            </div>

            <div class="details-card">
              <h2>Asset details</h2>
              <div class="meta-list">
                ${MetaRow("Title", "Evening Reflection")}
                ${MetaRow("Resolution", "2400 x 1500")}
                ${MetaRow("Captured", "May 2, 2026")}
                ${MetaRow("Collection", "Travel inspiration")}
              </div>
            </div>
          </aside>
        `;
      }

      function DeleteDialog() {
        return `
          <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
            <div class="dialog-card">
              <div class="dialog-icon" aria-hidden="true">!</div>
              <h2 id="dialog-title" class="dialog-title">Delete image?</h2>
              <p id="dialog-description" class="dialog-copy">
                Are you sure you want to delete this image from your library? This action cannot be undone.
              </p>
              <div class="dialog-actions">
                ${Button({
                  className: "button-secondary",
                  label: "Cancel",
                  extra: 'id="cancel-delete"'
                })}
                ${Button({
                  className: "button-danger",
                  label: "Delete image",
                  extra: 'id="confirm-delete"'
                })}
              </div>
            </div>
          </dialog>
        `;
      }

      function App() {
        return `
          <main class="page-shell">
            <div class="app-card">
              <div class="app-grid">
                ${ImagePreview()}
                ${ImageDetails()}
              </div>
            </div>
          </main>
          <p class="sr-only" id="screen-reader-status" aria-live="polite"></p>
          ${DeleteDialog()}
        `;
      }

      document.getElementById("root").innerHTML = App();

      const dialog = document.getElementById("delete-dialog");
      const openButton = document.getElementById("open-dialog");
      const cancelButton = document.getElementById("cancel-delete");
      const confirmButton = document.getElementById("confirm-delete");
      const image = document.getElementById("preview-image");
      const deletedState = document.getElementById("deleted-state");
      const statusMessage = document.getElementById("status-message");
      const liveStatus = document.getElementById("screen-reader-status");

      let lastFocusedElement = null;

      function closeDialog() {
        if (dialog.open) {
          dialog.close();
        }
      }

      openButton.addEventListener("click", () => {
        lastFocusedElement = document.activeElement;
        dialog.showModal();
        cancelButton.focus();
      });

      cancelButton.addEventListener("click", closeDialog);

      dialog.addEventListener("click", (event) => {
        const bounds = dialog.getBoundingClientRect();
        const isOutside =
          event.clientX < bounds.left ||
          event.clientX > bounds.right ||
          event.clientY < bounds.top ||
          event.clientY > bounds.bottom;

        if (isOutside) {
          closeDialog();
        }
      });

      dialog.addEventListener("close", () => {
        if (lastFocusedElement instanceof HTMLElement) {
          lastFocusedElement.focus();
        }
      });

      confirmButton.addEventListener("click", () => {
        image.hidden = true;
        deletedState.style.display = "flex";
        openButton.disabled = true;
        openButton.setAttribute("aria-disabled", "true");
        statusMessage.textContent = "This image was deleted from your library.";
        liveStatus.textContent = "Image deleted from your library.";
        closeDialog();
        deletedState.focus();
      });
    </script>
  </body>
</html>
