               </p>
               <div class="dialog-actions">
                 ${Button({
                   className: "button-secondary",
                   label: "Cancel",
                   extra: 'id="cancel-delete"'
                 })}
                 ${Button({
                   className: "button-danger",
                   label: "Delete image",
                   extra: 'id="confirm-delete"'
                 })}
               </div>
             </div>
           </dialog>
         `;
       }

